-- Legacy role columns removed (T-2.7, D-36). Run the grant backfill BEFORE
-- this migration: it turns users.platform_role and memberships.role into
-- grants, and this migration drops both columns and their enum types.
--   pnpm --filter @nestself/api db:backfill-grants
-- The ALTER and DROP statements were generated by db:generate.
-- Guard (hand-added): refuse to drop a legacy role that has no backfilled
-- grant. Mapping: ADMIN -> platform_owner, OPERATIONS -> client_operations,
-- EXPERT -> expert, MANAGER -> team_manager, HR_ADMIN -> hr_admin (EMPLOYEE
-- needs no check). A membership's grant must be scoped to its organization.
DO $$
DECLARE
  offender text;
BEGIN
  SELECT u.id INTO offender
  FROM users u
  WHERE u.platform_role IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM grants g
      WHERE g.subject_user_id = u.id
        AND g.template_key = CASE u.platform_role::text
          WHEN 'ADMIN' THEN 'platform_owner'
          WHEN 'OPERATIONS' THEN 'client_operations'
          WHEN 'EXPERT' THEN 'expert'
        END
    )
  ORDER BY u.id
  LIMIT 1;

  IF offender IS NULL THEN
    SELECT m.user_id INTO offender
    FROM memberships m
    WHERE m.status = 'ACTIVE'
      AND m.role <> 'EMPLOYEE'
      AND NOT EXISTS (
        SELECT 1 FROM grants g
        WHERE g.subject_user_id = m.user_id
          AND g.scope_org_id = m.org_id
          AND g.template_key = CASE m.role::text
            WHEN 'MANAGER' THEN 'team_manager'
            WHEN 'HR_ADMIN' THEN 'hr_admin'
          END
      )
    ORDER BY m.user_id
    LIMIT 1;
  END IF;

  IF offender IS NOT NULL THEN
    RAISE EXCEPTION 'user % holds a legacy role without a backfilled grant; run db:backfill-grants before migration 0005', offender;
  END IF;
END
$$;--> statement-breakpoint
ALTER TABLE "users" DROP COLUMN "platform_role";--> statement-breakpoint
ALTER TABLE "memberships" DROP COLUMN "role";--> statement-breakpoint
DROP TYPE "public"."org_role";--> statement-breakpoint
DROP TYPE "public"."platform_role";